const width=rows[0].length,height=rows.length;
const cell=p=>({x:Math.max(0,Math.min(width-1,Math.floor(p.x*width/100))),y:Math.max(0,Math.min(height-1,Math.floor(p.y*height/100)))});
const point=(x,y)=>({x:(x+.5)*100/width,y:(y+.5)*100/height});
const free=(x,y)=>x>=0&&x<width&&y>=0&&y<height&&rows[y][x]==='1';
export function canStand(p){if(p.x<1||p.x>99||p.y<1||p.y>99)return false;const c=cell(p);return free(c.x,c.y)}
export function nearestLand(p){if(canStand(p))return {...p};let best=null,distance=Infinity;for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++)if(free(x,y)){const q=point(x,y),d=(q.x-p.x)**2+(q.y-p.y)**2;if(d<distance){distance=d;best=q}}return best}
export function findRoute(start,end){
 const a=cell(nearestLand(start)),b=cell(nearestLand(end)),key=(x,y)=>y*width+x;
 const queue=[a],parents=new Map([[key(a.x,a.y),null]]);let head=0;
 while(head<queue.length){const c=queue[head++],id=key(c.x,c.y);if(c.x===b.x&&c.y===b.y){const path=[];let i=id;while(parents.get(i)!==null){path.push(point(i%width,Math.floor(i/width)));i=parents.get(i)}return path.reverse()}
 for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const x=c.x+dx,y=c.y+dy,k=key(x,y);if(free(x,y)&&!parents.has(k)){parents.set(k,id);queue.push({x,y})}}
 }return null;
}
